const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const blackSeaPoint = ee.Geometry.Point(34.0, 43.0); // A central point in the Black Sea
  const geometry = blackSeaPoint.buffer(10000); // 10 km buffer around the point

  const dateMayStart = '2022-05-15';
  const dateMayEnd = '2022-05-25'; // +/- 5 days around May 20
  const dateJuneStart = '2022-06-15';
  const dateJuneEnd = '2022-06-25'; // +/- 5 days around June 20

  const SCALE = 1000; // Use a larger scale for faster computation and to avoid memory issues

  // Sentinel-2 cloud masking function (L2A products)
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
                 .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale reflectance to 0-1
  }

  // 2. Data Acquisition & Check for May
  let collectionMay = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(dateMayStart, dateMayEnd)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter for less cloudy images
    .map(maskS2clouds)
    .select('B2'); // B2 is the Blue band, often used for water brightness/clarity

  let sizeMay = collectionMay.size().getInfo();
  if (sizeMay === 0) {
    console.log("No Sentinel-2 images found for May 2022 in the specified region.");
    console.log("C1");
    return;
  }
  let imageMay = collectionMay.median();

  // 3. Data Acquisition & Check for June
  let collectionJune = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
    .filterBounds(geometry)
    .filterDate(dateJuneStart, dateJuneEnd)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
    .map(maskS2clouds)
    .select('B2');

  let sizeJune = collectionJune.size().getInfo();
  if (sizeJune === 0) {
    console.log("No Sentinel-2 images found for June 2022 in the specified region.");
    console.log("C1");
    return;
  }
  let imageJune = collectionJune.median();

  // Calculate valid pixel count for May
  let countMay = imageMay.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('B2').getInfo();

  if (countMay === 0) {
    console.log("May images exist, but 0 valid pixels remain after cloud masking.");
    console.log("C2");
    return;
  }

  // Calculate valid pixel count for June
  let countJune = imageJune.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('B2').getInfo();

  if (countJune === 0) {
    console.log("June images exist, but 0 valid pixels remain after cloud masking.");
    console.log("C2");
    return;
  }

  // 4. Calculation - Mean B2 (Blue band reflectance) for brightness
  let brightnessMay = imageMay.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('B2').getInfo();

  let brightnessJune = imageJune.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: SCALE,
    maxPixels: 1e9
  }).get('B2').getInfo();

  // 5. Validation & Final Answer
  if (brightnessMay === null || isNaN(brightnessMay) || brightnessJune === null || isNaN(brightnessJune)) {
    console.log("Calculation resulted in Null or NaN for brightness values.");
    console.log("C3");
    return;
  }

  console.log(`May (2022-05-20) Images: ${sizeMay} (Valid Pixels: ${countMay})`);
  console.log(`June (2022-06-20) Images: ${sizeJune} (Valid Pixels: ${countJune})`);
  console.log(`Mean Blue Band Reflectance (May): ${brightnessMay.toFixed(4)}`);
  console.log(`Mean Blue Band Reflectance (June): ${brightnessJune.toFixed(4)}`);

  if (brightnessJune > brightnessMay) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
